import type { ComponentProps, Key, MouseEventHandler, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Badge } from '../../atomic-elements/Badge'
import styles from './Feed.module.css'

export interface FeedItem {
  /** A stable key. Without it the index is the key, which is fine for a list re-rendered whole. */
  id?: Key
  /** An Avatar of who did it, or an Icon for the kind of event. Decorative: the sentence says it all. */
  media?: ReactNode
  /** Who did it, in bold. */
  actor: ReactNode
  /** The rest of the sentence: what they did, and to what ("changed the status of Harbor Lights"). */
  action: ReactNode
  /** When it happened. */
  at: Date
  /** What they wrote, in a box under the sentence. */
  comment?: ReactNode
  /** Makes the sentence a link, and the whole row clickable. Keep links out of `actor` and `action` then: links cannot nest. */
  href?: string
  /** Runs when the link is followed, e.g. to mark the item read. */
  onClick?: MouseEventHandler<HTMLAnchorElement>
  /** Not seen yet: a dot at the end of the row, read out as "Unread". */
  isUnread?: boolean
}

export interface FeedProps extends Omit<ComponentProps<'div'>, 'children'> {
  /** The events, in the order to show them; newest first is the norm. */
  items: FeedItem[]
  /** The vertical line joining one event to the next. */
  hasConnector?: boolean
  /** A form to add a comment, after the last event. The form is yours: the feed lines it up with the text. */
  composer?: ReactNode
  /** Shown instead of the list when there are no items. */
  empty?: ReactNode
  /** How the time reads. The `<time>` element carries the full ISO moment either way. */
  formatTime?: (at: Date) => string
}

const moment = new Intl.DateTimeFormat('en', { dateStyle: 'medium', timeStyle: 'short' })

/**
 * What happened, as a list of sentences: who did what to what, and when,
 * with an optional comment under each and an optional form to add one. It
 * owns no data and no landmark: the page names the region around it.
 */
export function Feed({
  items,
  hasConnector = true,
  composer,
  empty = 'No activity yet.',
  formatTime = (at) => moment.format(at),
  className,
  ...props
}: FeedProps) {
  return (
    <div className={cn(styles.feed, hasConnector && styles.connected, className)} {...props}>
      {items.length === 0 ? (
        <p className={styles.empty}>{empty}</p>
      ) : (
        <ol className={styles.items}>
          {items.map((item, i) => (
            <li key={item.id ?? i} className={styles.item} data-unread={item.isUnread || undefined}>
              <span className={styles.media} aria-hidden="true">
                {item.media}
              </span>
              <div className={styles.body}>
                <p className={styles.sentence}>
                  {item.href ? (
                    <a href={item.href} onClick={item.onClick} className={styles.link}>
                      <strong>{item.actor}</strong> {item.action}
                    </a>
                  ) : (
                    <>
                      <strong>{item.actor}</strong> {item.action}
                    </>
                  )}{' '}
                  <time className={styles.time} dateTime={item.at.toISOString()}>
                    {formatTime(item.at)}
                  </time>
                </p>
                {item.comment && <div className={styles.comment}>{item.comment}</div>}
              </div>
              {item.isUnread && <Badge isDot aria-label="Unread" className={styles.unread} />}
            </li>
          ))}
        </ol>
      )}
      {composer && <div className={styles.composer}>{composer}</div>}
    </div>
  )
}

/* One event a row: a round media column, the sentence beside it. With the
   connector, a line runs from each media to the next one, down the centre
   of the column. */
.feed {
  display: grid;
  gap: var(--space-4);
  min-inline-size: 0;
}

.items {
  display: grid;
  gap: var(--space-4);
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  position: relative;
  display: grid;
  grid-template-columns: var(--avatar-sm) minmax(0, 1fr);
  gap: var(--space-3);
}

/* The dot takes a column of its own at the end, so text never runs under it. */
.item[data-unread] {
  grid-template-columns: var(--avatar-sm) minmax(0, 1fr) auto;
}

/* Level with the media's centre, so it sits on the first line. */
.unread {
  margin-block-start: calc((var(--avatar-sm) - var(--badge-dot-md)) / 2);
}

.connected .item:not(:last-child)::before {
  content: '';
  position: absolute;
  inset-block: var(--avatar-sm) calc(-1 * var(--space-4));
  inset-inline-start: calc(var(--avatar-sm) / 2);
  border-inline-start: 1px solid var(--border);
}

/* An Icon sits in a filled circle; an Avatar of the same size covers it. */
.media {
  display: grid;
  place-items: center;
  inline-size: var(--avatar-sm);
  block-size: var(--avatar-sm);
  border-radius: var(--radius-full);
  background: var(--surface-filled);
  color: var(--muted-foreground);
}

.body {
  display: grid;
  gap: var(--space-2);
  min-inline-size: 0;
  /* Centres a one-line sentence on the media. */
  padding-block-start: calc((var(--avatar-sm) - var(--leading-body-sm)) / 2);
}

.sentence {
  margin: 0;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.sentence strong {
  font-weight: 500;
}

/* The row is the target: the link's box stretches over the whole item. */
.link {
  color: inherit;
  text-decoration: none;
}
.link::after {
  content: '';
  position: absolute;
  inset: 0;
}
.link:hover {
  text-decoration: underline;
}
.link:focus-visible {
  outline: none;
}
.link:focus-visible::after {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset);
  border-radius: var(--radius-sm);
}

.time {
  color: var(--muted-foreground);
  white-space: nowrap;
}

.comment {
  /* Above a linked row's stretched target, so links in the comment work. */
  position: relative;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--foreground);
  overflow-wrap: anywhere;
}

.empty {
  margin: 0;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
}

/* Lined up with the sentences, past the media column. */
.composer {
  margin-inline-start: calc(var(--avatar-sm) + var(--space-3));
}
